() => {
  const h1 = document.querySelector('h1');
  const cs = getComputedStyle(h1);
  return { color: cs.color, theme: document.documentElement.className };
}

() => {
  const targets = ['AI writes the code', 'More, not less', 'Your questions answered', 'Every Monday, we prove'];
  return targets.map(t => {
    const el = Array.from(document.querySelectorAll('h1,h2,h3,h4,p')).find(e => new RegExp(t).test(e.textContent.slice(0, 200)));
    if (!el) return { t, missing: true };
    const cs = getComputedStyle(el);
    let bg = cs.backgroundColor, cur = el;
    while (cur && (bg==='rgba(0, 0, 0, 0)'||bg==='transparent') && cur.parentElement) { cur = cur.parentElement; bg = getComputedStyle(cur).backgroundColor; }
    return { t, color: cs.color, effBg: bg };
  });
}

